import os, glob, docx, openpyxl, email
from docx.oxml.ns import qn
from docx.table import Table
from docx.text.paragraph import Paragraph
os.chdir('/filesystem/WrenParkway')
def dump_docx(path):
    d = docx.Document(path)
    out=[]
    for child in d.element.body.iterchildren():
        if child.tag == qn('w:p'):
            t = Paragraph(child, d).text
            if t.strip(): out.append(t)
        elif child.tag == qn('w:tbl'):
            tb = Table(child, d)
            out.append("[TABLE]")
            for r in tb.rows:
                out.append(" | ".join(c.text for c in r.cells))
            out.append("[/TABLE]")
    for s in d.sections:
        for p in s.header.paragraphs:
            if p.text.strip(): out.append("HEADER: "+p.text)
        for p in s.footer.paragraphs:
            if p.text.strip(): out.append("FOOTER: "+p.text)
    return "\n".join(out)
for f in glob.glob('**/*.docx', recursive=True):
    open('/tmp/txt/'+f.replace('/','__')+'.txt','w').write(dump_docx(f))
for f in glob.glob('**/*.xlsx', recursive=True):
    wb = openpyxl.load_workbook(f, data_only=False)
    out=[]
    for ws in wb.worksheets:
        out.append(f"===== SHEET {ws.title} (state={ws.sheet_state}) dims={ws.dimensions}")
        for row in ws.iter_rows():
            vals = [(c.coordinate, c.value) for c in row if c.value is not None]
            if vals: out.append(" | ".join(f"{k}={v}" for k,v in vals))
    open('/tmp/txt/'+f.replace('/','__')+'.txt','w').write("\n".join(out))
for f in glob.glob('**/*.eml', recursive=True):
    open('/tmp/txt/'+f.replace('/','__')+'.txt','w').write(open(f, errors='replace').read())
