    # decode hex strings <...> in TJ
    def h(m):
        try: return '(' + bytes.fromhex(m.group(1)).decode('latin-1') + ')'
        except: return m.group(0)
    return re.sub(r'<([0-9a-fA-F]+)>', h, s)
for pno in range(doc.page_count):
    page = doc[pno]
    xs = page.get_contents()
    for i, x in enumerate(xs):
        st = doc.xref_stream(x).decode('latin-1')
        # find overlay patterns: white filled rect followed by text
        if re.search(r'1 1 1 rg 1 1 1 RG [\d\.]+ [\d\.]+ [\d\.]+ [\d\.]+ re B', st) or re.search(r're\s*\nh\s*\n1 1 1 RG 1 1 1 rg B', st):
            for m in re.finditer(r'(q 1 1 1 rg 1 1 1 RG ([\d\.]+) ([\d\.]+) ([\d\.]+) ([\d\.]+) re B Q q 0 0 0 rg 0 0 0 RG BT/helv ([\d\.]+) Tf ([\d\.]+) ([\d\.]+) TD\[(.*?)\]TJ ET Q)', st):
